mitigation.zh:
登录首步只颁发 mfa-pending 限态会话，受保护接口统一校验完整认证状态，验证结果以服务端会话字段为准，客户端声明的通过字段一律忽略。
    // 登录首步成功：仅置 pending，绝非完整认证
    req.session.authStage = 'pending';
    // 受保护接口统一门禁
    app.use('/api', (req, res, next) => {
      if (req.session.authStage !== 'complete')
        return res.status(403).json({ error: 'mfa_required' });
      next();
    });

验证码校验下沉到统一登录服务层，表单与 JSON 路由共用同一守卫函数，杜绝按 Content-Type 分流的中间件差异。
    app.post(['/login', '/api/login'], rateLimit, captchaGuard, loginHandler);
    function captchaGuard(req, res, next) {
      const ok = captcha.verify(req.session.id, req.body.captcha);
      if (!ok) return res.status(400).json({ error: 'captcha_failed' });
      next();
    }

统一会话 Cookie 的名称、Domain 与 Path 并避免同名变体；采用 __Host- 前缀（强制无 Domain、Path=/、Secure），投掷的同名低特异性 Cookie 不再被优先读取。
    // Express：__Host- 前缀会话 Cookie
    res.cookie('__Host-session', sid, {
        secure: true, httpOnly: true, path: '/', sameSite: 'lax'
    });
    # 响应头形态
    Set-Cookie: __Host-session=abc123; Secure; HttpOnly; Path=/; SameSite=Lax

