mitigation.zh:
授权统一收敛到路由层并覆盖全部方法（含 HEAD/OPTIONS），显式拒绝未登记动词；路径规范化（合并斜杠、解码）先于授权执行且跨协议一致。
    # Nginx：未登记动词拒绝 + 路径规范化
    if ($request_method !~ ^(GET|POST|HEAD|OPTIONS)$) { return 405; }
    merge_slashes on;
    // Spring Security：兜底全拒绝，授权作用于规范化后路径
    http.authorizeHttpRequests(a -> a
        .requestMatchers("/admin/**").hasRole("ADMIN")
        .anyRequest().denyAll());

凭据字段进入查询前强制标量类型，操作符对象直接拒绝；启用 ODM 净化选项（$ne 等对象被强制按等值处理），并返回统一认证失败信息。
    // Node/Mongoose：开启过滤器净化
    mongoose.set('sanitizeFilter', true);
    // 显式类型守卫：非字符串凭据拒绝
    if (typeof body.user !== 'string' || typeof body.pass !== 'string')
        return res.status(400).end();
    const u = await User.findOne({ user: body.user, pass: body.pass });

发起授权时生成加密随机 state 存入会话，回调时严格比对并一次性消费；不匹配立即终止流程，防止攻击者 code 注入受害者会话（登录 CSRF）。
    // 发起：随机 state 入会话
    const state = crypto.randomBytes(16).toString('hex');
    req.session.oauthState = state;
    res.redirect(authorizeUrl + '&state=' + state);
    // 回调：比对并消费
    if (!req.session.oauthState || state !== req.session.oauthState)
        return res.status(403).end('state mismatch');
    delete req.session.oauthState;

认证入口对凭据显式断言字符串类型，非字符串（数组/对象）一律 400 拒绝；比较使用恒时严格函数，杜绝松散相等与类型戏法。
    // PHP：类型断言 + 恒时比较
    foreach (['user', 'pass'] as $k) {
        if (!isset($_POST[$k]) || !is_string($_POST[$k])) {
            http_response_code(400); exit('bad request');
        }
    }
    $ok = $storedHash && hash_equals($storedHash, hash('sha256', $pass, true));

