mitigation.zh:
把"已验证"状态写入服务端会话或一次性流程票据（绑定账号+短时效），设密端点强制校验该状态；完成后立即作废票据，前端步骤不可作为凭据。
    // 验证通过：发放一次性票据（10 分钟）
    const ticket = crypto.randomBytes(16).toString('hex');
    await redis.set(`reset:${ticket}`, account, 'EX', 600);
    // 设密端点：原子消费票据并比对账号
    const acct = await redis.getdel(`reset:${ticket}`);
    if (!acct || acct !== body.account) return res.sendStatus(403);

重置链接主机固定取服务端配置域名，忽略请求 Host 与 X-Forwarded-Host；Host 与配置不符的请求直接拒绝，令牌不落入外域链接。
    // 基址只来自环境配置
    const BASE = new URL(process.env.PUBLIC_ORIGIN);
    if (req.get('host') !== BASE.host) return res.sendStatus(400);
    const link = `${BASE.origin}/reset?token=${token}`;
    sendMail(email, link);

令牌签发时写入账号标识并 HMAC 签名，确认接口校验令牌、账号与会话三者一致；令牌存储只保留哈希，跨账号组合直接拒绝。
    // 签发：raw = account.expires，HMAC 签名
    const raw = `${account}.${expires}`;
    const token = Buffer.from(raw).toString('base64url') + '.' +
        crypto.createHmac('sha256', process.env.RESET_KEY).update(raw).digest('base64url');
    // 确认：验签后必须比对账号一致
    if (verifiedAccount !== body.account)
        return res.status(403).json({ error: 'mismatch' });

令牌消费与口令更新放进同一原子事务，成功即烧毁令牌记录；保留使用日志与告警，重放返回明确失效错误。
    -- 原子消费：仅当未使用时才能更新
    UPDATE reset_tokens
       SET used_at = NOW(), password_hash = :new_hash
     WHERE token_hash = :h AND used_at IS NULL AND expires_at > NOW();
    -- affected=0 → 令牌已用/过期，拒绝并告警
    // Java 侧事务包裹并检查影响行数
    if (jdbc.update(sql, params) == 0) throw new TokenConsumedException();

会话 Cookie 采用 SameSite=Strict（至少登录态区分严格策略），服务端按 Sec-Fetch-Site 拒绝跨站发起的状态变更请求。
    // Express：严格 SameSite
    res.cookie('session', sid, { sameSite: 'strict', secure: true, httpOnly: true });
    // 状态变更接口：校验 Sec-Fetch-Site
    const site = req.get('sec-fetch-site');
    if (site === 'cross-site' && req.method !== 'GET' && req.method !== 'HEAD')
        return res.status(403).json({ error: 'cross-site' });

账户查找前对 NameID 统一规范化（NFKC 归一、去首尾空白、小写化），逻辑收敛为单一工具方法且与 IdP 配置对齐，规范化后再比对账户映射，任一步失败即拒绝断言。
    String canonicalNameId(String raw) {
        String n = Normalizer.normalize(raw, Normalizer.Form.NFKC)
                              .trim().toLowerCase(Locale.ROOT);
        if (n.isEmpty() || n.chars().anyMatch(c -> c < 0x20))
            throw new IllegalArgumentException("invalid NameID");
        return n;
    }

认证状态变化时调用框架会话再生接口强制轮换 ID 并使旧会话立即失效；预认证发放的 Cookie 值在认证后不可复用。
    // Servlet 3.1+：登录成功后轮换会话 ID
    HttpSession s = request.getSession(false);
    if (s != null) request.changeSessionId();
    s.setAttribute("uid", user.getId());
    // Express：等价再生
    req.session.regenerate(() => { req.session.uid = user.id; });

登录查询改参数化绑定，口令以哈希恒时比较校验；用户名做长度与字符白名单。
    // PHP
    $st = $pdo->prepare('SELECT password_hash FROM users WHERE username = ?');
    $st->execute([$username]);
    $u = $st->fetch();
    $ok = $u && password_verify($password, $u['password_hash']);
    // Java 同理
    try (PreparedStatement ps = conn.prepareStatement(
        "SELECT password_hash FROM users WHERE username=?")) { ps.setString(1, username); }

仅在直接边界代理层清洗 XFF 等覆盖类头，应用侧显式配置可信代理网段，未列来源的头一律不可信，路由按真实请求行解析。
    // Express：仅信任指定代理
    app.set('trust proxy', ['loopback', '10.0.0.0/8']);
    # Nginx 边界层：固定转发头，覆盖客户端注入值
    proxy_set_header X-Forwarded-For  $remote_addr;
    proxy_set_header X-Forwarded-Host $host;

