    order.amount = product.price * order.qty          # 服务端重算
    if order.qty <= 0 or order.amount <= 0: abort(400)
    if not rsa_verify(PLATFORM_PUB, raw_body, headers['X-Sign']):
        abort(403)                                    # 回调验签+金额核对

