    dest = Path(dest_dir).resolve()
    for zi in zf.infolist():
        target = (dest / zi.filename).resolve()
        if not str(target).startswith(str(dest) + os.sep):
            raise ValueError(f'zip slip: {zi.filename}')

拒绝含控制字节的文件名，改用逻辑标识到物理路径的允许列表映射，全部组件消费同一映射结果，不再拼接动态路径。
    $allow = ['manual.pdf' => '/srv/files/manual.pdf',
              'logo.png'   => '/srv/files/logo.png'];
    $name  = $_GET['file'] ? '';
    if (preg_match('/[\x00-\x1f\x7f]/', $name)) { http_response_code(400); exit; }
    $file = $allow[$name] ? null;
    if ($file === null) { http_response_code(404); exit; }
    readfile($file);

下载参数只做单一解码，统一规范化后在真实路径上强制根目录前缀校验，并推荐改用服务端对象标识而非用户可控路径。
    Path root   = Paths.get(storageDir).toRealPath();
    Path target = root.resolve(requested).normalize().toRealPath();
    if (!target.startsWith(root))
        throw new SecurityException("path escape");

下载参数禁止任何 stream wrapper 形态：含 scheme、父目录段或控制字节直接 400，仅允许相对文件名并做 realpath 根目录校验。
    if (preg_match('#^[a-zA-Z][\w+.-]*://#', $p) || strpos($p, '..') !== false
        || strpbrk($p, "\\\x00") !== false) { http_response_code(400); exit; }
    $real = realpath($baseDir . '/' . basename($p));
    if ($real === false || strpos($real, $baseReal . DIRECTORY_SEPARATOR) !== 0) exit;

各层统一长度上限（如 255 字节）并在超限时直接拒绝而非截断，最终路径以 realpath 校验根目录前缀后才打开。
    if (strlen($name) > 255) { http_response_code(400); exit('name too long'); }
    $real = realpath($baseDir . '/' . $name);
    if ($real === false || strpos($real, $baseReal . DIRECTORY_SEPARATOR) !== 0)
        { http_response_code(403); exit; }

拒绝终止字节与路径填充等控制字符，改用逻辑标识允许列表映射物理文件，各层消费同一映射结果，杜绝截断差异。
    ALLOWED = {'logo.png': 'static/logo.png', 'report.pdf': 'static/report.pdf'}
    if any(ord(c) < 0x20 or ord(c) == 0x7f for c in name):
        abort(400)
    path = ALLOWED.get(name) or abort(404)

应用层拒绝以 UNC、双斜杠或盘符开头的路径并禁止其进入支持网络解析的 API；主机层封禁服务账户出站 SMB 消除侧信道。
    if (name.startsWith("\\\\") || name.startsWith("//")
            || name.matches("^[A-Za-z]:.*")) {
        throw new SecurityException("UNC/absolute path rejected");
    }
