        -Name NtfsDisable8dot3NameCreation -Value 1

声明 Content-Type 仅作提示，类型判定以服务端内容检测为准并与扩展名交叉校验，对象名服务端生成，上传目录禁止执行。
    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $real  = $finfo->file($_FILES['file']['tmp_name']);
    if (!in_array($real, ['image/jpeg', 'image/png', 'application/pdf'], true))
        { http_response_code(415); exit('type not allowed'); }
    # nginx：上传目录禁执行
    location /uploads/ { location ~* \.php$ { return 403; } }

存储名由服务端生成（随机对象名+白名单扩展名），入口、存储与静态服务层消费同一规范化结果，消除多扩展名解释差异；上传目录不可执行。
    $ext = strtolower(pathinfo($_FILES['file']['name'], PATHINFO_EXTENSION));
    if (!in_array($ext, ['jpg', 'jpeg', 'png', 'pdf'], true))
        { http_response_code(415); exit; }
    $stored = bin2hex(random_bytes(16)) . '.' . $ext;

文件名校验直接拒绝冒号与 NTFS 保留流语法（::$DATA 等），整体采用"字符白名单+单扩展"约束；生成服务端对象名，上传目录不可执行。
    // Java：严格白名单从源头排除冒号与流语法
    if (!name.matches("[A-Za-z0-9_-]{1,64}\\.(jpg|png|pdf)"))
        throw new UploadRejectedException(name);

原始文件名拒绝一切控制字节，各层消费同一净化结果；存储名由服务端生成，杜绝 NUL 截断差异；上传目录不可执行。
    if (preg_match('/[\x00-\x1f\x7f]/', $_FILES['file']['name'] ? '')) {
        http_response_code(400); exit('bad filename');
    }
    $stored = bin2hex(random_bytes(16)) . '.' . $ext;

上传后引用改用逻辑 ID 允许列表映射到固定物理路径，拒绝控制字节、动态路径与 zip://、phar:// 等运行时 wrapper；上传目录不可执行。
    // PHP：按逻辑 ID 取白名单映射，杜绝 wrapper 直达
    $map = ['a1' => '/srv/store/obj-a1.bin'];
    if (!isset($map[$id]) || preg_match('#^(zip|phar|file|data|expect)://#i', $id)) {
        http_response_code(400); exit('bad reference');
    }
    readfile($map[$id]);

升级到受支持的 PHP 版本，输入完成 URL 解码后拒绝 NUL 与控制字符，再解析规范绝对路径并在文件 API 前强制固定根目录：
    $raw = rawurldecode($_GET['p'] ? '');
    if (preg_match('/[\x00-\x1f\x7f]/', $raw)) { http_response_code(400); exit; }
    $path = realpath(APP_ROOT . '/' . $raw);
    if ($path === false || !str_starts_with($path, APP_ROOT)) exit('denied');

