      // 文件读取：白名单 ID + realpath 前缀校验
      $p = realpath($root . '/' . preg_replace('/[^a-z0-9\-]/i', '', $_GET['id']));
      if (!$p || !str_starts_with($p, $root)) exit('forbidden');
  修复后用第 1 步样例回归，file URI 应在入口即被拒绝。

